/**
 * A `member` gets a read-only view of the same form; only an owner sees
 * the danger zone.
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";

import { WorkspaceSettingsForm } from "@/components/workspace/workspace-settings-form";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export default async function WorkspaceSettingsPage() {
  const t = await getTranslations("workspace-settings");
  const { workspace, membership } = await requireWorkspace();

  const canEdit = membership.role === "owner" || membership.role === "admin";
  const isOwner = membership.role === "owner";

  return (
    <div className="space-y-6">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle level={2}>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      <WorkspaceSettingsForm
        workspace={workspace}
        canEdit={canEdit}
        isOwner={isOwner}
      />
    </div>
  );
}

"use client";

/**
 * Workspace settings form — name/slug editor plus an owner-only danger
 * zone. Owners and admins can edit; a plain member sees a read-only
 * form. Only an owner sees the delete-workspace control, gated behind
 * a confirmation dialog whose button is held, not clicked.
 */

import { useEffect, useState, useTransition, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { updateWorkspace, deleteWorkspace } from "@/actions/workspace";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { HoldActionButton } from "@/components/ui/hold-action-button";

interface WorkspaceSettingsFormProps {
  workspace: {
    id: string;
    name: string;
    slug: string;
    logo?: string | null;
  };
  canEdit: boolean;
  isOwner: boolean;
}

export function WorkspaceSettingsForm({
  workspace,
  canEdit,
  isOwner,
}: WorkspaceSettingsFormProps) {
  const t = useTranslations("workspace-settings");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [name, setName] = useState(workspace.name);
  const [slug, setSlug] = useState(workspace.slug);
  const [error, setError] = useState<string | null>(null);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  /**
   * Read after mount, never during render: the server has no window,
   * and an origin baked into the HTML would differ from the browser's
   * on any deployment reached by more than one hostname. Until it
   * arrives the helper shows the path alone, which is already true.
   */
  const [origin, setOrigin] = useState("");
  useEffect(() => setOrigin(window.location.origin), []);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);

    startTransition(async () => {
      const result = await updateWorkspace({ name, slug });
      if (!result.success) {
        setError(result.error);
        return;
      }
      toast.success(t("form.updated"));
      router.refresh();
    });
  }

  function handleDelete() {
    setIsDeleting(true);
    startTransition(async () => {
      const result = await deleteWorkspace();
      if (!result.success) {
        toast.error(result.error);
        setIsDeleting(false);
        setDeleteOpen(false);
        return;
      }
      toast.success(t("dangerZone.deleted"));
      router.push("/dashboard");
      router.refresh();
    });
  }

  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle>{t("form.generalTitle")}</CardTitle>
          <CardDescription>{t("form.generalDescription")}</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && <p className="text-sm text-destructive">{error}</p>}

            <div className="space-y-2">
              <Label htmlFor="name">{t("form.nameLabel")}</Label>
              <Input
                id="name"
                value={name}
                onChange={(event) => setName(event.target.value)}
                disabled={!canEdit || isPending}
                required
                minLength={2}
                maxLength={50}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="slug">{t("form.urlLabel")}</Label>
              <Input
                id="slug"
                value={slug}
                onChange={(event) => setSlug(event.target.value)}
                disabled={!canEdit || isPending}
                required
                minLength={2}
                maxLength={50}
                pattern="[a-z0-9-]+"
              />
              {/* The address the typed slug produces, not the saved one. */}
              <p className="text-xs text-muted-foreground">
                {origin}/{slug}
              </p>
            </div>

            {canEdit ? (
              <div className="flex justify-end">
                <Button type="submit" disabled={isPending}>
                  {isPending ? t("form.savePending") : t("form.save")}
                </Button>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">
                {t("form.readOnlyNote")}
              </p>
            )}
          </form>
        </CardContent>
      </Card>

      {isOwner && (
        <Card className="border-destructive/30">
          <CardHeader>
            <CardTitle className="text-destructive">
              {t("dangerZone.title")}
            </CardTitle>
            <CardDescription>{t("dangerZone.description")}</CardDescription>
          </CardHeader>
          <CardContent>
            <Dialog open={deleteOpen} onOpenChange={setDeleteOpen}>
              <DialogTrigger render={<Button variant="destructive" />}>
                {t("dangerZone.trigger")}
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>{t("dangerZone.dialogTitle")}</DialogTitle>
                  <DialogDescription>
                    {t("dangerZone.dialogDescription", {
                      name: workspace.name,
                    })}
                  </DialogDescription>
                </DialogHeader>
                <DialogFooter>
                  <Button
                    variant="outline"
                    onClick={() => setDeleteOpen(false)}
                    disabled={isDeleting}
                  >
                    {t("dangerZone.cancel")}
                  </Button>
                  {/* Held, not clicked: a workspace goes with everything in it. */}
                  <HoldActionButton
                    size="default"
                    onConfirm={handleDelete}
                    disabled={isDeleting}
                    labels={{
                      holding: t("dangerZone.holding"),
                      complete: t("dangerZone.confirmPending"),
                      description: t("dangerZone.holdDescription"),
                      confirmed: t("dangerZone.confirmPending"),
                    }}
                  >
                    {isDeleting
                      ? t("dangerZone.confirmPending")
                      : t("dangerZone.confirm")}
                  </HoldActionButton>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </CardContent>
        </Card>
      )}
    </>
  );
}

"use server";

/**
 * Workspace settings server actions — thin transport over the bound
 * workspace service (`@/lib/workspace`): parse input with the schemas
 * from `@intelligo-dev/auth`, call the service, map any
 * `WorkspaceServiceError` to a friendly message, and revalidate the
 * page. No business rules here — those live in the service.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import {
  isWorkspaceServiceError,
  updateWorkspaceSchema,
  type UpdateWorkspaceInput,
} from "@intelligo-dev/auth";

import { workspace } from "@/lib/workspace";

export type WorkspaceActionResult<T = undefined> =
  { success: true; data: T } | { success: false; error: string };

type Translator = Awaited<
  ReturnType<typeof getTranslations<"workspace-settings">>
>;

function friendlyMessage(t: Translator): Partial<Record<string, string>> {
  return {
    forbidden: t("errors.forbidden"),
    invalid_input: t("errors.invalidInput"),
    not_found: t("errors.notFound"),
    workspace_limit_reached: t("errors.workspaceLimitReached"),
    provider_error: t("errors.providerError"),
  };
}

function friendlyError(error: unknown, t: Translator): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isWorkspaceServiceError(error)) {
    return friendlyMessage(t)[error.code] ?? t("errors.somethingWentWrong");
  }
  return t("errors.somethingWentWrong");
}

export async function updateWorkspace(
  input: UpdateWorkspaceInput
): Promise<WorkspaceActionResult> {
  const t = await getTranslations("workspace-settings");
  const parsed = updateWorkspaceSchema.safeParse(input);
  if (!parsed.success) {
    return {
      success: false,
      error: parsed.error.issues[0]?.message ?? t("errors.invalidInput"),
    };
  }

  try {
    await workspace.updateWorkspace(parsed.data);
    revalidatePath("/settings/workspace");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

export async function deleteWorkspace(): Promise<WorkspaceActionResult> {
  const t = await getTranslations("workspace-settings");
  try {
    await workspace.deleteWorkspace();
    revalidatePath("/", "layout");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

import "server-only";

/**
 * Binds the plan's workspace limit (`checkPlanLimit`,
 * `@intelligo-dev/billing`) into the workspace service
 * (`@intelligo-dev/auth`).
 *
 * `checkPlanLimit` is keyed by `workspaceId`, but the service's
 * `checkWorkspaceLimit` port is keyed by `userId`: a new workspace has
 * no id to check a plan against yet. This binding checks the plan of
 * the user's oldest workspace instead.
 */

import { eq } from "drizzle-orm";

import { db } from "@intelligo-dev/core/db";
import { member } from "@intelligo-dev/core/db/schema";
import { createWorkspaceService } from "@intelligo-dev/auth";
import { checkPlanLimit } from "@intelligo-dev/billing";

export const workspace = createWorkspaceService({
  checkWorkspaceLimit: async (userId, currentCount) => {
    const [membership] = await db
      .select({ organizationId: member.organizationId })
      .from(member)
      .where(eq(member.userId, userId))
      .orderBy(member.createdAt)
      .limit(1);

    // No existing workspace to price a plan against yet — allow. The
    // service itself never calls this port for a caller's first
    // workspace, but a defensive default keeps this binding correct on
    // its own too.
    if (!membership) {
      return { allowed: true, limit: -1 };
    }

    const result = await checkPlanLimit(
      membership.organizationId,
      "workspaces",
      currentCount
    );
    return { allowed: result.allowed, limit: result.limit };
  },
});

"use client";

/**
 * Error boundary for workspace settings. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="settings-workspace" />;
}
